package com.example.starter.blackstart;

import java.time.Instant;

/**
 * 黑启动计划。
 * 状态机：IN_PROGRESS（执行中） -&gt; STARTED（第三步成功，已启动）或 TERMINATED（值班员终止）。
 * 进入终态后记录只读；currentStep 为当前待执行步骤号（1~3），固定三步不允许跳步。
 */
public record BlackStartPlan(
        long id,
        String status,
        int currentStep,
        Instant createdAt,
        Instant completedAt,
        Instant terminatedAt,
        String terminationReason) {

    /** 执行中。 */
    public static final String STATUS_IN_PROGRESS = "IN_PROGRESS";
    /** 已启动（终态）。 */
    public static final String STATUS_STARTED = "STARTED";
    /** 已终止（终态）。 */
    public static final String STATUS_TERMINATED = "TERMINATED";

    /** 计划固定步数：电池母线带电、逆变器同步、关键负载接入。 */
    public static final int TOTAL_STEPS = 3;
    /** 第三步关键负载接入功率上限，单位 kW。 */
    public static final double MAX_LOAD_POWER_KW = 200.0;
    /** 母线电压合格下限，单位 V。 */
    public static final double MIN_VOLTAGE_V = 380.0;
    /** 母线电压合格上限，单位 V。 */
    public static final double MAX_VOLTAGE_V = 420.0;
    /** 频率合格下限，单位 Hz。 */
    public static final double MIN_FREQUENCY_HZ = 49.5;
    /** 频率合格上限，单位 Hz。 */
    public static final double MAX_FREQUENCY_HZ = 50.5;
}
'@, $enc)
[System.IO.File]::WriteAllText("$dir\StepAttempt.java", @'
package com.example.starter.blackstart;

import java.time.Instant;

/**
 * 一次步骤确认记录（含成功与被拒绝的失败记录）。
 * 读数单位：电压 V、频率 Hz、功率 kW；recordedAt 为 UTC 时刻；
 * 未提供的读数与成功记录的 rejectReason 为 null。
 */
public record StepAttempt(
        long id,
        long planId,
        int stepNo,
        String requestId,
        String outcome,
        String deviceStatus,
        Double voltageV,
        Double frequencyHz,
        Double powerKw,
        String rejectReason,
        Instant recordedAt) {

    /** 确认成功。 */
    public static final String OUTCOME_SUCCESS = "SUCCESS";
    /** 被拒绝（读数越界、设备状态错误或跳步）。 */
    public static final String OUTCOME_REJECTED = "REJECTED";
    /** 可成功的设备状态。 */
    public static final String DEVICE_STATUS_NORMAL = "NORMAL";
}
'@, $enc)
[System.IO.File]::WriteAllText("$dir\ConfirmStepRequest.java", @'
package com.example.starter.blackstart;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 值班员步骤确认请求。
 * requestId 为幂等键：同键同参重放返回首个结果，同键异参返回 409。
 * 读数单位：voltageV 伏特、frequencyHz 赫兹、powerKw 千瓦（仅第三步必填）。
 */
public record ConfirmStepRequest(
        @NotBlank String requestId,
        @NotBlank String deviceStatus,
        @NotNull Double voltageV,
        @NotNull Double frequencyHz,
        Double powerKw) {
}
'@, $enc)
[System.IO.File]::WriteAllText("$dir\ConfirmStepResponse.java", @'
package com.example.starter.blackstart;

import java.time.Instant;

/**
 * 步骤确认响应。outcome 为 SUCCESS 或 REJECTED；被拒绝时 rejectReason 说明原因，步骤号不推进。
 */
public record ConfirmStepResponse(
        long planId,
        int stepNo,
        String requestId,
        String outcome,
        String rejectReason,
        String planStatus,
        int currentStep,
        Instant recordedAt) {
}
'@, $enc)
[System.IO.File]::WriteAllText("$dir\TerminateRequest.java", @'
package com.example.starter.blackstart;

import jakarta.validation.constraints.NotBlank;

/**
 * 值班员终止计划请求，reason 记录为终止原因。
 */
public record TerminateRequest(@NotBlank String reason) {
}
'@, $enc)
[System.IO.File]::WriteAllText("$dir\PlanView.java", @'
package com.example.starter.blackstart;

import java.time.Instant;
import java.util.List;

/**
 * 黑启动计划查询视图：当前步骤、每步读数与拒绝理由、终止或完成时刻（UTC）。
 */
public record PlanView(
        long planId,
        String status,
        int currentStep,
        Instant createdAt,
        Instant completedAt,
        Instant terminatedAt,
        String terminationReason,
        List<StepView> steps) {

    /**
     * 单步视图。stepNo 为 1~3；succeeded 表示该步是否已成功；
     * attempts 为该步全部确认记录（含被拒绝记录），按记录时刻升序。
     */
    public record StepView(
            int stepNo,
            boolean succeeded,
            Instant succeededAt,
            List<AttemptView> attempts) {
    }

    /**
     * 单次确认记录视图：读数（V/Hz/kW，未提供为 null）、结果与拒绝理由、UTC 记录时刻。
     */
    public record AttemptView(
            String requestId,
            String outcome,
            String deviceStatus,
            Double voltageV,
            Double frequencyHz,
            Double powerKw,
            String rejectReason,
            Instant recordedAt) {
    }
}
'@, $enc)
Write-Output done"}

